mapper.select:
select count(*) as totalReviewDays,
       sum(case when t.daily_profit_pct > 0 then 1 else 0 end) as profitDays,
       sum(case when t.daily_profit_pct < 0 then 1 else 0 end) as lossDays,
       ifnull(avg(t.daily_profit_pct), 0) as avgDailyProfitPct,
       sum(case when t.win_trade_count > 0 and t.trade_count > 0 then 1 else 0 end) as winDays,
       sum(case when t.trade_count > 0 then 1 else 0 end) as tradeDays
from t_trial_daily_review t

    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

select date_format(t.review_date, '%Y-%m-%d') as date, t.emotion_temp as score
from t_trial_daily_review t

    t.emotion_temp is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

order by t.review_date asc

select t.market_status as code, count(*) as count
from t_trial_daily_review t

    t.market_status is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

group by t.market_status order by count desc

select date_format(t.review_date, '%Y-%m-%d') as date,
       ifnull(t.limit_up_count, 0) as limitUp,
       ifnull(t.limit_down_count, 0) as limitDown,
       ifnull(t.continuous_board_count, 0) as continuousBoard
from t_trial_daily_review t

    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

order by t.review_date asc

select tmp.sector as code, count(*) as count
from (
    select t.main_sector1 as sector from t_trial_daily_review t
    where t.main_sector1 is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}
    union all
    select t.main_sector2 as sector from t_trial_daily_review t
    where t.main_sector2 is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}
    union all
    select t.main_sector3 as sector from t_trial_daily_review t
    where t.main_sector3 is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}
) tmp
group by tmp.sector order by count desc

select t.adapt_system as code, count(*) as count
from t_trial_daily_review t

    t.adapt_system is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

group by t.adapt_system order by count desc

select date_format(t.review_date, '%Y-%m-%d') as date, t.operation_self_rating as rating
from t_trial_daily_review t

    t.operation_self_rating is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

order by t.review_date asc

select date_format(t.review_date, '%Y-%m-%d') as date, ifnull(t.daily_profit_pct, 0) as profit
from t_trial_daily_review t

    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

order by t.review_date asc

select date_format(t.review_date, '%Y-%m-%d') as date, ifnull(t.north_flow_amount, 0) as amount
from t_trial_daily_review t

    t.north_flow_amount is not null
    and t.review_date >= #{startTime}
    and t.review_date <= #{endTime}
    and t.owner = #{owner}

order by t.review_date asc

select t.psychology as code, count(*) as count from t_trial_trade_record t
t.psychology is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.psychology order by count desc

select t.psychology as code, ifnull(avg(t.profit_pct), 0) as avgProfit from t_trial_trade_record t
t.psychology is not null and t.profit_pct is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.psychology order by avgProfit desc

select t.time_slot as code, count(*) as count from t_trial_trade_record t
t.time_slot is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.time_slot order by count desc

select t.trade_direction as code, count(*) as count from t_trial_trade_record t
t.trade_direction is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.trade_direction order by count desc

select date_format(t.trade_datetime, '%Y-%m-%d') as date, avg(t.execute_rating) as rating from t_trial_trade_record t
t.execute_rating is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by date_format(t.trade_datetime, '%Y-%m-%d') order by date asc

select t.follow_plan as code, count(*) as count from t_trial_trade_record t
t.follow_plan is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.follow_plan order by count desc

select t.stock_name as stockName, t.stock_code as stockCode, count(*) as count from t_trial_trade_record t
t.stock_code is not null and t.trade_datetime >= #{startTime} and t.trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY) and t.owner = #{owner}
group by t.stock_code, t.stock_name order by count desc limit 10

select date_format(r.review_date, '%Y-%m-%d') as date,
       ifnull(r.daily_profit_pct, 0) as profit,
       ifnull(tc.tradeCount, 0) as tradeCount
from t_trial_daily_review r
left join (
    select date_format(trade_datetime, '%Y-%m-%d') as td, owner, count(*) as tradeCount
    from t_trial_trade_record

        and trade_datetime >= #{startTime}
        and trade_datetime < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

    group by date_format(trade_datetime, '%Y-%m-%d'), owner
) tc on tc.td = date_format(r.review_date, '%Y-%m-%d') and tc.owner = r.owner

    and r.review_date >= #{startTime}
    and r.review_date <= #{endTime}
    and r.owner = #{owner}

order by r.review_date asc
